import { HugeiconsIcon } from "@hugeicons/react";
import Search01Icon from "@hugeicons/core-free-icons/Search01Icon";

import { InputGroup, InputGroupAddon, InputGroupInput } from "@/registry/erbium/ui/input-group";
import { Kbd } from "@/registry/erbium/ui/kbd";

export function InputGroupKbd() {
  return (
    <InputGroup className="max-w-sm">
      <InputGroupInput placeholder="Search..." />
      <InputGroupAddon>
        <HugeiconsIcon icon={Search01Icon} className="text-muted-foreground" />
      </InputGroupAddon>
      <InputGroupAddon align="inline-end">
        <Kbd hotkey="Mod+K" />
      </InputGroupAddon>
    </InputGroup>
  );
}

import { InputGroupKbd } from "../examples/input-group-kbd";

const Example = () => <InputGroupKbd />;

export default Example;
